-- Frozen v5 schema from the pre-account-space Room export. One statement per line.
CREATE TABLE IF NOT EXISTS `contacts` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `name` TEXT NOT NULL, `avatarUrl` TEXT, `avatarPath` TEXT, `note` TEXT, `bio` TEXT, `pinyinInitial` TEXT NOT NULL, `platforms` TEXT, `createTime` INTEGER NOT NULL, `updateTime` INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS `contact_fields` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `fieldName` TEXT NOT NULL, `fieldKey` TEXT NOT NULL, `icon` TEXT, `sortOrder` INTEGER NOT NULL, `isSystem` INTEGER NOT NULL, `isEnabled` INTEGER NOT NULL, `createTime` INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS `custom_fields` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `fieldName` TEXT NOT NULL, `fieldType` TEXT NOT NULL, `options` TEXT NOT NULL, `sortOrder` INTEGER NOT NULL, `isEnabled` INTEGER NOT NULL, `createTime` INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS `contact_field_values` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `contactId` INTEGER NOT NULL, `fieldId` INTEGER, `customFieldId` INTEGER, `value` TEXT NOT NULL, `createTime` INTEGER NOT NULL, `updateTime` INTEGER NOT NULL, FOREIGN KEY(`contactId`) REFERENCES `contacts`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`fieldId`) REFERENCES `contact_fields`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`customFieldId`) REFERENCES `custom_fields`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_contact_field_values_contactId_fieldId` ON `contact_field_values` (`contactId`, `fieldId`);
CREATE INDEX IF NOT EXISTS `index_contact_field_values_contactId_customFieldId` ON `contact_field_values` (`contactId`, `customFieldId`);
CREATE INDEX IF NOT EXISTS `index_contact_field_values_contactId` ON `contact_field_values` (`contactId`);
CREATE TABLE IF NOT EXISTS `card_collections` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `name` TEXT NOT NULL, `description` TEXT, `backgroundImagePath` TEXT, `dominantColor` INTEGER, `createTime` INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS `scan_results` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `contactId` INTEGER NOT NULL, `collectionId` INTEGER NOT NULL, `scannedTime` INTEGER NOT NULL, `sourceType` TEXT NOT NULL, `rawData` TEXT, `ocrText` TEXT, `qrCodeContent` TEXT, `confidence` REAL NOT NULL, FOREIGN KEY(`contactId`) REFERENCES `contacts`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`collectionId`) REFERENCES `card_collections`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_scan_results_contactId_collectionId` ON `scan_results` (`contactId`, `collectionId`);
CREATE INDEX IF NOT EXISTS `index_scan_results_collectionId` ON `scan_results` (`collectionId`);
CREATE INDEX IF NOT EXISTS `index_scan_results_contactId` ON `scan_results` (`contactId`);
CREATE TABLE IF NOT EXISTS `user_profile` (`id` INTEGER NOT NULL, `name` TEXT NOT NULL, `avatarPath` TEXT, `cardImagePath` TEXT, `bio` TEXT, `platforms` TEXT, `defaultPlatform` TEXT, `updateTime` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `contact_platforms` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `contactId` INTEGER NOT NULL, `platformKey` TEXT NOT NULL, `value` TEXT, `displayName` TEXT, `jumpLink` TEXT NOT NULL, `originalLink` TEXT, `avatarUrl` TEXT, FOREIGN KEY(`contactId`) REFERENCES `contacts`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_contact_platforms_contactId` ON `contact_platforms` (`contactId`);
CREATE INDEX IF NOT EXISTS `index_contact_platforms_platformKey` ON `contact_platforms` (`platformKey`);
CREATE UNIQUE INDEX IF NOT EXISTS `index_contact_platforms_contactId_platformKey` ON `contact_platforms` (`contactId`, `platformKey`);
CREATE VIRTUAL TABLE IF NOT EXISTS `contacts_fts` USING FTS4(`name` TEXT NOT NULL, `note` TEXT, `bio` TEXT, content=`contacts`);
CREATE TRIGGER IF NOT EXISTS room_fts_content_sync_contacts_fts_BEFORE_UPDATE BEFORE UPDATE ON `contacts` BEGIN DELETE FROM `contacts_fts` WHERE `docid`=OLD.`rowid`; END;
CREATE TRIGGER IF NOT EXISTS room_fts_content_sync_contacts_fts_BEFORE_DELETE BEFORE DELETE ON `contacts` BEGIN DELETE FROM `contacts_fts` WHERE `docid`=OLD.`rowid`; END;
CREATE TRIGGER IF NOT EXISTS room_fts_content_sync_contacts_fts_AFTER_UPDATE AFTER UPDATE ON `contacts` BEGIN INSERT INTO `contacts_fts`(`docid`, `name`, `note`, `bio`) VALUES (NEW.`rowid`, NEW.`name`, NEW.`note`, NEW.`bio`); END;
CREATE TRIGGER IF NOT EXISTS room_fts_content_sync_contacts_fts_AFTER_INSERT AFTER INSERT ON `contacts` BEGIN INSERT INTO `contacts_fts`(`docid`, `name`, `note`, `bio`) VALUES (NEW.`rowid`, NEW.`name`, NEW.`note`, NEW.`bio`); END;
CREATE TABLE IF NOT EXISTS `tags` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `name` TEXT NOT NULL, `color` INTEGER NOT NULL, `pinyinInitial` TEXT NOT NULL, `source` TEXT NOT NULL, `showDot` INTEGER NOT NULL, `createTime` INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS `index_tags_name` ON `tags` (`name`);
CREATE TABLE IF NOT EXISTS `contact_tag` (`contactId` INTEGER NOT NULL, `tagId` INTEGER NOT NULL, `source` TEXT NOT NULL, `confidence` REAL NOT NULL, `createTime` INTEGER NOT NULL, PRIMARY KEY(`contactId`, `tagId`), FOREIGN KEY(`contactId`) REFERENCES `contacts`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`tagId`) REFERENCES `tags`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_contact_tag_tagId` ON `contact_tag` (`tagId`);
CREATE INDEX IF NOT EXISTS `index_contact_tag_contactId_source` ON `contact_tag` (`contactId`, `source`);
CREATE VIRTUAL TABLE IF NOT EXISTS `tags_fts` USING FTS4(`name` TEXT NOT NULL, `pinyinInitial` TEXT, content=`tags`);
CREATE TRIGGER IF NOT EXISTS room_fts_content_sync_tags_fts_BEFORE_UPDATE BEFORE UPDATE ON `tags` BEGIN DELETE FROM `tags_fts` WHERE `docid`=OLD.`rowid`; END;
CREATE TRIGGER IF NOT EXISTS room_fts_content_sync_tags_fts_BEFORE_DELETE BEFORE DELETE ON `tags` BEGIN DELETE FROM `tags_fts` WHERE `docid`=OLD.`rowid`; END;
CREATE TRIGGER IF NOT EXISTS room_fts_content_sync_tags_fts_AFTER_UPDATE AFTER UPDATE ON `tags` BEGIN INSERT INTO `tags_fts`(`docid`, `name`, `pinyinInitial`) VALUES (NEW.`rowid`, NEW.`name`, NEW.`pinyinInitial`); END;
CREATE TRIGGER IF NOT EXISTS room_fts_content_sync_tags_fts_AFTER_INSERT AFTER INSERT ON `tags` BEGIN INSERT INTO `tags_fts`(`docid`, `name`, `pinyinInitial`) VALUES (NEW.`rowid`, NEW.`name`, NEW.`pinyinInitial`); END;
CREATE TABLE IF NOT EXISTS room_master_table (id INTEGER PRIMARY KEY,identity_hash TEXT);
INSERT OR REPLACE INTO room_master_table (id,identity_hash) VALUES(42, '63d5cc9b16f6cf475e5e9fcef7532c1d');
